const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const vm = require('node:vm');
const { spawnSync } = require('node:child_process');
const { FakeDocument } = require('./browser-fakes.js');

const outputDirectory = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-query-load-more-'));
const outputPath = path.join(outputDirectory, 'queryStream.js');
const sourceRoot = path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts/ts');
const compilation = spawnSync('tsc', [
    '--target', 'ES2017', '--lib', 'ES2017,DOM', '--skipLibCheck', '--outFile', outputPath,
    path.join(sourceRoot, 'template.ts'), path.join(sourceRoot, 'queryStream.ts')
], { encoding: 'utf8' });
assert.equal(compilation.status, 0, compilation.stdout + compilation.stderr);
const compiledSource = fs.readFileSync(outputPath, 'utf8');

class MemoryWorker {
    constructor() {
        this.rows = [];
        this.messages = [];
        this.listeners = new Map();
        this.terminated = false;
        this.storeId = 'test-' + Math.random();
    }

    addEventListener(type, callback) {
        this.listeners.set(type, [...(this.listeners.get(type) || []), callback]);
    }

    removeEventListener(type, callback) {
        this.listeners.set(type, (this.listeners.get(type) || []).filter(value => value !== callback));
    }

    postMessage(message) {
        this.messages.push(message);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: true, storeId: this.storeId };
            if (message.op === 'append') {
                this.rows.push(...message.rows);
            } else if (message.op === 'read') {
                response.rows = this.rows.slice(message.start, message.start + message.count);
            } else if (message.op === 'truncate') {
                this.rows.length = message.count;
            } else if (message.op === 'dispose') {
                this.rows = [];
                response.disposed = true;
            }
            response.count = this.rows.length;
            for (const callback of this.listeners.get('message') || []) callback({ data: response });
        });
    }

    terminate() { this.terminated = true; }
}

function loadApi() {
    const document = new FakeDocument();
    const storage = () => {
        const values = new Map();
        return {
            get length() { return values.size; },
            key(index) { return [...values.keys()][index] || null; },
            getItem(key) { return values.get(key) || null; },
            setItem(key, value) { values.set(key, String(value)); },
            removeItem(key) { values.delete(key); }
        };
    };
    const window = {
        addEventListener() {}, removeEventListener() {}, dispatchEvent() { return true; },
        requestAnimationFrame(callback) { setImmediate(callback); },
        getComputedStyle(element) {
            return Object.assign({
                lineHeight: '24px', fontSize: '14px', paddingTop: '0px', paddingBottom: '0px',
                borderTopWidth: '0px', borderBottomWidth: '0px', marginBlockStart: '8px',
                direction: 'ltr', opacity: '1'
            }, element && element.style || {});
        },
        matchMedia() { return { matches: true }; },
        sessionStorage: storage(), localStorage: storage()
    };
    document.defaultView = window;
    const context = vm.createContext({
        workbench: {}, document, window, URL, URLSearchParams, AbortController,
        TextDecoder, Event: class { constructor(type) { this.type = type; } },
        setTimeout, clearTimeout
    });
    vm.runInContext(compiledSource, context, { filename: outputPath });
    return { api: context.workbench.queryStream, workbench: context.workbench, document, window };
}

function response(records) {
    let index = 0;
    return {
        ok: true, status: 200,
        body: {
            getReader() {
                return {
                    async read() {
                        if (index === records.length) return { done: true };
                        return { done: false, value: new TextEncoder().encode(JSON.stringify(records[index++]) + '\n') };
                    },
                    async cancel() { index = records.length; }
                };
            }
        }
    };
}

function batch(values, offset = 0, hasMore = false, extra = {}) {
    return [
        { type: 'head', version: 1 }, { type: 'view', id: 'tuple' },
        { type: 'vars', values: ['value'] },
        { type: 'namespaces', values: [{ prefix: 'ex', name: 'urn:example:' }] },
        { type: 'rows', values: values.map(value => [{ kind: 'literal', value: String(value) }]) },
        { type: 'end', metadata: Object.assign({
            'result-offset': offset, 'result-limit': 2, 'result-batch-count': values.length,
            'result-has-more': hasMore, 'result-next-offset': offset + values.length
        }, extra) }
    ];
}

function execution(options = {}) {
    const loaded = loadApi();
    const { api, document } = loaded;
    const form = document.createElement('form');
    form.setAttribute('action', '/repositories/owned/query');
    const controls = {};
    for (const [name, value] of Object.entries(Object.assign({
        query: 'SELECT ?value WHERE { VALUES ?value { 0 1 2 3 } }',
        queryLn: 'SPARQL', infer: 'true', 'query-timeout': '60',
        limit_query: '100', offset: '100', know_total: '1000', 'batch-size': '2'
    }, options.controls))) {
        if (value === null) continue;
        const control = document.createElement('input');
        control.name = name;
        control.value = value;
        controls[name] = control;
        form.appendChild(control);
    }
    const target = document.createElement('section');
    target.id = 'query-results';
    document.body.appendChild(form);
    document.body.appendChild(target);
    const requests = [];
    const workers = [];
    const responses = [...(options.responses || [batch([0, 1], 0, true)])];
    const controller = api.bindMainQueryForm(form, target, {
        maxDomRows: options.maxDomRows || 8,
        features: options.features,
        rowStoreOptions: { workerFactory() { const worker = new MemoryWorker(); workers.push(worker); return worker; } },
        async fetcher(url, init) {
            requests.push({ url, init });
            const next = responses.shift();
            if (typeof next === 'function') return next(url, init);
            return response(next);
        }
    });
    return Object.assign(loaded, { form, controls, target, requests, workers, responses, controller });
}

async function settle() {
    for (let count = 0; count < 5; count++) await new Promise(resolve => setImmediate(resolve));
}

module.exports = { MemoryWorker, loadApi, response, batch, execution, settle };
